#include <stdio.h>
#include <string.h>

#include "cmds.h"

#define SEQKIT_VERSION "1.5-r133"

static int print_usage(void)
{
	fprintf(stderr, "\n");
	fprintf(stderr, "Usage:   seqtk <command> <arguments>\n");
	fprintf(stderr, "Version: %s\n\n", SEQKIT_VERSION);
	fprintf(stderr, "Command: seq       common transformation of FASTA/Q\n");
	fprintf(stderr, "         size      report the number sequences and bases\n");
	fprintf(stderr, "         comp      get the nucleotide composition of FASTA/Q\n");
	fprintf(stderr, "         sample    subsample sequences\n");
	fprintf(stderr, "         subseq    extract subsequences from FASTA/Q\n");
	fprintf(stderr, "         fqchk     fastq QC (base/quality summary)\n");
	fprintf(stderr, "         mergepe   interleave two PE FASTA/Q files\n");
	fprintf(stderr, "         split     split one file into multiple smaller files\n");
	fprintf(stderr, "         trimfq    trim FASTQ using the Phred algorithm\n\n");
	fprintf(stderr, "         hety      regional heterozygosity\n");
	fprintf(stderr, "         gc        identify high- or low-GC regions\n");
	fprintf(stderr, "         mutfa     point mutate FASTA at specified positions\n");
	fprintf(stderr, "         mergefa   merge two FASTA/Q files\n");
	fprintf(stderr, "         famask    apply a X-coded FASTA to a source FASTA\n");
	fprintf(stderr, "         dropse    drop unpaired from interleaved PE FASTA/Q\n");
	fprintf(stderr, "         rename    rename sequence names\n");
	fprintf(stderr, "         randbase  choose a random base from hets\n");
	fprintf(stderr, "         cutN      cut sequence at long N\n");
	fprintf(stderr, "         gap       get the gap locations\n");
	fprintf(stderr, "         listhet   extract the position of each het\n");
	fprintf(stderr, "         hpc       homopolyer-compressed sequence\n");
	fprintf(stderr, "         telo      identify telomere repeats in asm or long reads\n\n");
	return 1;
}

int main(int argc, char *argv[])
{
	if (argc == 1) return print_usage();
	if (strcmp(argv[1], "seq") == 0) return cmd_seq(argc - 1, argv + 1);
	else if (strcmp(argv[1], "size") == 0) return cmd_size(argc - 1, argv + 1);
	else if (strcmp(argv[1], "comp") == 0) return cmd_comp(argc - 1, argv + 1);
	else if (strcmp(argv[1], "sample") == 0) return cmd_sample(argc - 1, argv + 1);
	else if (strcmp(argv[1], "subseq") == 0) return cmd_subseq(argc - 1, argv + 1);
	else if (strcmp(argv[1], "fqchk") == 0) return cmd_fqchk(argc - 1, argv + 1);
	else if (strcmp(argv[1], "mergepe") == 0) return cmd_mergepe(argc - 1, argv + 1);
	else if (strcmp(argv[1], "split") == 0) return cmd_split(argc - 1, argv + 1);
	else if (strcmp(argv[1], "trimfq") == 0) return cmd_trimfq(argc - 1, argv + 1);
	else if (strcmp(argv[1], "hety") == 0) return cmd_hety(argc - 1, argv + 1);
	else if (strcmp(argv[1], "gc") == 0) return cmd_gc(argc - 1, argv + 1);
	else if (strcmp(argv[1], "mutfa") == 0) return cmd_mutfa(argc - 1, argv + 1);
	else if (strcmp(argv[1], "mergefa") == 0) return cmd_mergefa(argc - 1, argv + 1);
	else if (strcmp(argv[1], "famask") == 0) return cmd_famask(argc - 1, argv + 1);
	else if (strcmp(argv[1], "dropse") == 0) return cmd_dropse(argc - 1, argv + 1);
	else if (strcmp(argv[1], "rename") == 0) return cmd_rename(argc - 1, argv + 1);
	else if (strcmp(argv[1], "randbase") == 0) return cmd_randbase(argc - 1, argv + 1);
	else if (strcmp(argv[1], "cutN") == 0) return cmd_cutn(argc - 1, argv + 1);
	else if (strcmp(argv[1], "gap") == 0) return cmd_gap(argc - 1, argv + 1);
	else if (strcmp(argv[1], "listhet") == 0) return cmd_listhet(argc - 1, argv + 1);
	else if (strcmp(argv[1], "hpc") == 0) return cmd_hpc(argc - 1, argv + 1);
	else if (strcmp(argv[1], "telo") == 0) return cmd_telo(argc - 1, argv + 1);
	else {
		fprintf(stderr, "[main] unrecognized command '%s'. Abort!\n", argv[1]);
		return 1;
	}
	return 0;
}
